function getImgList(){
    var p = "chapterImages = \\[(.*?)\\]";
    var p1 = "chapterPath = \"(.*?)\"";
    var chapterPath  = html.match(p1)[1];
    var path = html.match(p)[1].replace(/\"/g, "").split(",");
    var piclist = new Array([path.length]);
    for (var i = 0; i < path.length; i++) {
        piclist[i] = "http://res.gufengmh8.com/"+chapterPath + path[i];
    }
    return piclist;
}@Header:{Referer:thisPage}

